  ('sent-ex-zaruoenai-1', 'lang-ja', '会議を中止せざるを得ない。', 'かいぎ お ちゅうし せざる お えない。', 'lvl-ja-n3', 'authored', true),
  ('sent-ex-zaruoenai-2', 'lang-ja', '彼の意見に賛成せざるを得ない。', 'かれ の いけん に さんせい せざる お えない。', 'lvl-ja-n3', 'authored', true),
  ('sent-ex-zaruoenai-3', 'lang-ja', '早く出かけざるを得ない。', 'はやく でかけざる お えない。', 'lvl-ja-n3', 'authored', true),
  ('sent-ex-zaruoenai-4', 'lang-ja', '値段を下げざるを得ない。', 'ねだん お さげざる お えない。', 'lvl-ja-n3', 'authored', true),
