INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-okudasai-1', 'sent-ex-okudasai-1', 'en', 'Please take a seat.', 'authored'),
  ('st-ex-okudasai-2', 'sent-ex-okudasai-2', 'en', 'One moment, please.', 'authored'),
  ('st-ex-okudasai-3', 'sent-ex-okudasai-3', 'en', 'Please ring tomorrow.', 'authored'),
  ('st-ex-okudasai-4', 'sent-ex-okudasai-4', 'en', 'Please read it later.', 'authored'),
  ('st-ex-zaruoenai-1', 'sent-ex-zaruoenai-1', 'en', 'We have no choice but to call off the meeting.', 'authored'),
  ('st-ex-zaruoenai-2', 'sent-ex-zaruoenai-2', 'en', 'I cannot help but agree with his view.', 'authored'),
  ('st-ex-zaruoenai-3', 'sent-ex-zaruoenai-3', 'en', 'I have no choice but to leave early.', 'authored'),
  ('st-ex-zaruoenai-4', 'sent-ex-zaruoenai-4', 'en', 'We have no option but to lower the price.', 'authored'),
  ('st-ex-nichigainai-1', 'sent-ex-nichigainai-1', 'en', 'He must know.', 'authored'),
  ('st-ex-nichigainai-2', 'sent-ex-nichigainai-2', 'en', 'That shop is bound to be expensive.', 'authored'),
  ('st-ex-nichigainai-3', 'sent-ex-nichigainai-3', 'en', 'This must be his book.', 'authored'),
  ('st-ex-nichigainai-4', 'sent-ex-nichigainai-4', 'en', 'She must have forgotten.', 'authored'),
  ('st-ex-osoregaaru-1', 'sent-ex-osoregaaru-1', 'en', 'There is a risk that a typhoon will come.', 'authored'),
  ('st-ex-osoregaaru-2', 'sent-ex-osoregaaru-2', 'en', 'There is a danger the river will rise.', 'authored'),
  ('st-ex-osoregaaru-3', 'sent-ex-osoregaaru-3', 'en', 'There is a risk the illness will spread.', 'authored'),
  ('st-ex-osoregaaru-4', 'sent-ex-osoregaaru-4', 'en', 'There is a danger of an accident happening.', 'authored'),
  ('st-ex-kanenai-1', 'sent-ex-kanenai-1', 'en', 'Driving like that, he could well cause an accident.', 'authored'),
  ('st-ex-kanenai-2', 'sent-ex-kanenai-2', 'en', 'He is quite capable of saying it.', 'authored'),
  ('st-ex-kanenai-3', 'sent-ex-kanenai-3', 'en', 'Overdo it and you could well end up ill.', 'authored'),
  ('st-ex-kanenai-4', 'sent-ex-kanenai-4', 'en', 'If you do not sleep you could well collapse.', 'authored'),
  ('st-ex-gachi-1', 'sent-ex-gachi-1', 'en', 'He tends to forget his promises.', 'authored'),
  ('st-ex-gachi-2', 'sent-ex-gachi-2', 'en', 'I have a tendency to buy the cheap thing.', 'authored'),
  ('st-ex-gachi-3', 'sent-ex-gachi-3', 'en', 'I tend to use the same words.', 'authored'),
  ('st-ex-gachi-4', 'sent-ex-gachi-4', 'en', 'On my days off I tend to oversleep.', 'authored'),
  ('st-ex-ppoi-1', 'sent-ex-ppoi-1', 'en', 'He is forgetful.', 'authored'),
  ('st-ex-ppoi-2', 'sent-ex-ppoi-2', 'en', 'There is something childish about him.', 'authored'),
  ('st-ex-ppoi-3', 'sent-ex-ppoi-3', 'en', 'Those clothes look cheap.', 'authored'),
  ('st-ex-ppoi-4', 'sent-ex-ppoi-4', 'en', 'He is quick to anger.', 'authored'),
  ('st-ex-darake-1', 'sent-ex-darake-1', 'en', 'My clothes got covered in mud.', 'authored'),
  ('st-ex-darake-2', 'sent-ex-darake-2', 'en', 'His essay is full of mistakes.', 'authored'),
  ('st-ex-darake-3', 'sent-ex-darake-3', 'en', 'The desk is covered in books.', 'authored'),
  ('st-ex-darake-4', 'sent-ex-darake-4', 'en', 'My hands are covered in cuts.', 'authored'),
  ('st-ex-mukemuki-1', 'sent-ex-mukemuki-1', 'en', 'It is a book for children.', 'authored'),
  ('st-ex-mukemuki-2', 'sent-ex-mukemuki-2', 'en', 'That room faces south.', 'authored'),
  ('st-ex-mukemuki-3', 'sent-ex-mukemuki-3', 'en', 'It is a price aimed at students.', 'authored'),
  ('st-ex-mukemuki-4', 'sent-ex-mukemuki-4', 'en', 'That shop is aimed at young people.', 'authored'),
  ('st-ex-chuu-1', 'sent-ex-chuu-1', 'en', 'The phone rang while I was playing a game.', 'authored'),
  ('st-ex-chuu-2', 'sent-ex-chuu-2', 'en', 'Please be quiet during the test.', 'authored'),
  ('st-ex-chuu-3', 'sent-ex-chuu-3', 'en', 'My older brother is at work on his part-time job.', 'authored'),
  ('st-ex-chuu-4', 'sent-ex-chuu-4', 'en', 'Please do not come in during the lesson.', 'authored')
